using System.Text.Json;
using DES.Modules.Rules.Contracts;
using DES.Modules.Rules.Runtime;
using FluentValidation;

namespace DES.Modules.Rules.Features;

public sealed class SearchRulesQueryValidator : AbstractValidator<SearchRulesQuery> { public SearchRulesQueryValidator() { RuleFor(x => x.PageNumber).GreaterThan(0); RuleFor(x => x.PageSize).InclusiveBetween(1, 100); RuleFor(x => x.Search).MaximumLength(200); RuleFor(x => x.Sort).Must(x => x is null or "name" or "-name" or "created" or "-created" or "updated" or "-updated"); RuleFor(x => x.Categories).MaximumLength(256).Must(RuleSearchFilters.IsValidCategoryList).WithMessage("Categories must be a comma-separated list of rule categories."); RuleFor(x => x.Severity).Must(x => string.IsNullOrWhiteSpace(x) || RuleSearchFilters.Severities.Contains(x.Trim(), StringComparer.Ordinal)).WithMessage("Severity must be Error, Warning, or Info."); RuleFor(x => x.Tag).MaximumLength(64); RuleFor(x => x.Archived).IsInEnum(); } }
public sealed class CreateRuleCommandValidator : AbstractValidator<CreateRuleCommand> { public CreateRuleCommandValidator() { RuleFor(x => x.StableCode).NotEmpty().MaximumLength(64).Matches("^[A-Za-z0-9_.-]+$"); RuleFor(x => x.Name).NotEmpty().MaximumLength(200); RuleFor(x => x.Description).MaximumLength(2000); RuleFor(x => x.AstJson).Must(ValidAst); RuleFor(x => x.OutcomeJson).Must(JsonObject); } internal static bool ValidAst(string value) { try { RuleAstSerializer.Parse(value); return true; } catch (JsonException) { return false; } catch (ArgumentException) { return false; } } internal static bool JsonObject(string value) { try { using JsonDocument d = JsonDocument.Parse(value); return d.RootElement.ValueKind == JsonValueKind.Object; } catch (JsonException) { return false; } } }
public sealed class UpdateRuleDraftCommandValidator : AbstractValidator<UpdateRuleDraftCommand> { public UpdateRuleDraftCommandValidator() { RuleFor(x => x.DefinitionId).NotEmpty(); RuleFor(x => x.VersionId).NotEmpty(); RuleFor(x => x.ExpectedAggregateVersion).GreaterThan(0); RuleFor(x => x.Name).NotEmpty().MaximumLength(200); RuleFor(x => x.Description).MaximumLength(2000); RuleFor(x => x.AstJson).Must(CreateRuleCommandValidator.ValidAst); RuleFor(x => x.OutcomeJson).Must(CreateRuleCommandValidator.JsonObject); } }
public sealed class SubmitRuleForReviewCommandValidator : AbstractValidator<SubmitRuleForReviewCommand> { public SubmitRuleForReviewCommandValidator() { RuleFor(x => x.DefinitionId).NotEmpty(); RuleFor(x => x.VersionId).NotEmpty(); RuleFor(x => x.ExpectedAggregateVersion).GreaterThan(0); } }
public sealed class PublishRuleCommandValidator : AbstractValidator<PublishRuleCommand> { public PublishRuleCommandValidator() { RuleFor(x => x.DefinitionId).NotEmpty(); RuleFor(x => x.VersionId).NotEmpty(); RuleFor(x => x.ExpectedAggregateVersion).GreaterThan(0); } }
public sealed class RetireRuleCommandValidator : AbstractValidator<RetireRuleCommand> { public RetireRuleCommandValidator() { RuleFor(x => x.DefinitionId).NotEmpty(); RuleFor(x => x.VersionId).NotEmpty(); RuleFor(x => x.ExpectedAggregateVersion).GreaterThan(0); } }
public sealed class ClonePublishedRuleCommandValidator : AbstractValidator<ClonePublishedRuleCommand> { public ClonePublishedRuleCommandValidator() { RuleFor(x => x.DefinitionId).NotEmpty(); RuleFor(x => x.VersionId).NotEmpty(); RuleFor(x => x.ExpectedAggregateVersion).GreaterThan(0); } }
public sealed class DeleteRuleCommandValidator : AbstractValidator<DeleteRuleCommand> { public DeleteRuleCommandValidator() { RuleFor(x => x.DefinitionId).NotEmpty(); RuleFor(x => x.ExpectedAggregateVersion).GreaterThan(0); } }
public sealed class RestoreRuleCommandValidator : AbstractValidator<RestoreRuleCommand> { public RestoreRuleCommandValidator() { RuleFor(x => x.DefinitionId).NotEmpty(); RuleFor(x => x.ExpectedAggregateVersion).GreaterThan(0); } }
public sealed class TestRuleCommandValidator : AbstractValidator<TestRuleCommand> { public TestRuleCommandValidator() { RuleFor(x => x.AstJson).Must(CreateRuleCommandValidator.ValidAst); RuleFor(x => x.Documents).NotNull().Must(x => x.Count <= 20).Must(x => x.Sum(d => d.Key.Length + d.Value.Length) <= 1_048_576); RuleForEach(x => x.Documents).Must(x => x.Key.Length is > 0 and <= 64 && x.Value.Length <= 262_144 && IsJsonObject(x.Value)); RuleFor(x => x.ParametersJson).Must(IsParametersObject); } private static bool IsJsonObject(string json) { try { using JsonDocument d = JsonDocument.Parse(json); return d.RootElement.ValueKind == JsonValueKind.Object; } catch (JsonException) { return false; } } private static bool IsParametersObject(string? json) { try { RuleParameterContext.Parse(json); return true; } catch (JsonException) { return false; } catch (ArgumentException) { return false; } } }
